//! LC04: printed red/Throne identity; mandatory entry discard then collective sacrifice.
//! Seat-order choices reuse the original frame; no removal until all sacrifice choices finish.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="LC04";
pub(crate) const KEY:&str="lc04-entry-tribute";
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Picks{pub chosen:Vec<Option<String>>}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn definition()->Definition{let mut d=with_abilities(vec![ability(KEY,"进场强制：每位玩家弃一手牌，然后各牺牲角色、附属、暗藏者、资产",Timing::Fast,vec![],vec![],vec![Op::ForEachLivingPlayer(vec![Op::Discard{player:PlayerRef::Context,count:Some(1),redraw:false,optional:false}]),Op::LC04Sacrifices],Some(Event::Enter))]);d.traits.chaos=true;d}
fn uses(v:&[Op])->bool{v.iter().any(|o|match o{Op::LC04Sacrifices=>true,Op::ForEachLivingPlayer(b)|Op::ForEachLivingPlayerFromActor(b)=>uses(b),Op::IfTargetExhausted{exhausted,ready,..}=>uses(std::slice::from_ref(exhausted))||uses(std::slice::from_ref(ready)),_=>false})}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("lc04-")||uses(&a.ops)||a.modes.iter().any(|m|uses(&m.ops))}
fn owned(f:&ResolutionFrame)->bool{f.ability_key.starts_with("lc04-")||f.steps.iter().any(|s|uses(std::slice::from_ref(&s.op)))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!same(a,&definition().abilities[0]){return Err("卡德兰完整进场程序不能改写或移植".into())}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("卡德兰混乱及完整进场程序必须保留".into())}Ok(())}
impl Game{
 fn lc04_source(&self,actor:usize,s:&SourceSnapshot)->RuleResult<()>{let c=&s.card;if actor>=self.players.len()||c.controller!=actor||c.owner>=self.players.len()||c.definition!=ID||c.face_down||!self.mystic_instance_valid(&c.id)||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("卡德兰进场来源身份损坏".into())}self.mobility_immutable_identity(c)}
 pub(crate) fn lc04_forced(&mut self,d:&Declaration)->RuleResult<bool>{if !related(&d.ability){return Ok(false)}validate_ability(&d.source.card.definition,&d.ability)?;self.lc04_source(d.actor,&d.source)?;if !self.players[d.actor].eliminated{let f=self.make_frame(d.actor,d.source.clone(),&d.ability,vec![],vec![],None);self.dispatch_frame(f,d.ability.label.clone(),None,ResponsePolicy::Respondable);}Ok(true)}
 pub(crate) fn lc04_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !owned(f){return Ok(())}self.lc04_source(f.actor,&f.source)?;self.validate_resource_frame(f)?;let Some(last)=f.steps.last()else{return Err("卡德兰缺少程序".into())};let discards=&f.steps[..f.steps.len()-1];let seats=discards.iter().map(|s|s.context).collect::<Vec<_>>();if f.ability_key!=KEY||!self.mystic_instance_valid(&f.frame_id)||f.frame_id==f.source.card.id||f.cursor>f.steps.len()||f.chosen_region.is_some()||!f.targets.is_empty()||!f.already_paid.is_empty()||!f.resource_payments.is_empty()||last.context!=f.actor||!matches!(last.op,Op::LC04Sacrifices)||seats.is_empty()||seats.iter().any(|s|*s>=self.players.len())||seats.windows(2).any(|w|w[0]>=w[1])||self.players.iter().any(|p|!p.eliminated&&!seats.contains(&p.seat))||discards.iter().any(|s|!matches!(s.op,Op::Discard{player:PlayerRef::Context,count:Some(1),redraw:false,optional:false}))||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor>0&&!matches!(f.guard,GuardState::Accepted){return Err("卡德兰须先全体弃牌再完整四类牺牲，保留原游标".into())}Ok(())}
 fn lc04_options(&self,slot:usize,prior:&[Option<String>])->Vec<ChoiceOption>{let seat=slot/4;let kind=slot%4;if seat>=self.players.len()||self.players[seat].eliminated{return vec![]}let chosen=prior.iter().flatten().collect::<BTreeSet<_>>();if kind==3{return self.players[seat].assets.iter().filter(|c|!chosen.contains(&c.id)).map(|c|self.option(c,seat,None,Some("asset"))).collect()}
 self.in_play_cards().into_iter().filter(|(r,c)|c.controller==seat&&!chosen.contains(&c.id)&&match kind{0=>r.is_some()&&!c.face_down&&catalog::card(&c.definition).kind=="character",1=>!c.face_down&&self.attachments.iter().any(|a|a.card.id==c.id&&self.attachment_host_valid(a)),2=>r.is_some()&&c.face_down,_=>false}).map(|(r,c)|self.option(c,seat,r,None)).collect()}
 fn lc04_picks(&self,f:&ResolutionFrame,p:&Picks)->RuleResult<()>{self.lc04_frame(f)?;if !owned(f)||f.cursor!=f.steps.len()||p.chosen.len()>self.players.len()*4{return Err("卡德兰牺牲阶段错误".into())}for(i,id)in p.chosen.iter().enumerate(){let opts=self.lc04_options(i,&p.chosen[..i]);if match id{Some(id)=>!opts.iter().any(|o|&o.id==id),None=>!opts.is_empty()}{return Err("卡德兰不能跳过合法类别、重复对象或移植选择".into())}}Ok(())}
 fn lc04_title(slot:usize)->String{format!("卡德兰大王：选择牺牲一个{}",["角色","附属","暗藏者","资产"][slot%4])}
 pub(crate) fn lc04_offer(&mut self,f:ResolutionFrame,mut p:Picks)->RuleResult<()>{self.lc04_picks(&f,&p)?;while p.chosen.len()<self.players.len()*4{let slot=p.chosen.len();let opts=self.lc04_options(slot,&p.chosen);if opts.is_empty(){p.chosen.push(None);continue}self.choice(slot/4,"lc04-sacrifice",Self::lc04_title(slot),opts,1,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::LC04(p)});return Ok(())}
 // Freeze every selected source before any host/control grant leaves. Remove
 // selected attached children before their hosts; one physical object once.
 let mut ids=p.chosen.iter().flatten().filter(|id|self.in_play(id).is_some()).cloned().collect::<Vec<_>>();
 let depth=|id:&str|{let mut current=id.to_string();let mut seen=BTreeSet::new();while seen.insert(current.clone()){let Some(a)=self.attachments.iter().find(|a|a.card.id==current)else{break};current=a.host_id.clone();}seen.len()};
 ids.sort_by_key(|id|std::cmp::Reverse(depth(id)));
 let wave=ids.into_iter().map(|id|{let(r,c)=self.in_play(&id).unwrap();let s=self.source_snapshot(c,r);(id,RemovalCause::Sacrifice,s)}).collect();self.destroy_wave_as(f.actor,wave);
 for(slot,id)in p.chosen.into_iter().enumerate(){if slot%4!=3{continue}if let Some(id)=id{let seat=slot/4;let i=self.players[seat].assets.iter().position(|c|c.id==id).ok_or("卡德兰原资产已离开")?;let c=self.players[seat].assets.remove(i);self.note(format!("{}牺牲资产{}",player_id(seat),catalog::card(&c.definition).name));let c=self.reset_zone_card(c);self.commit_owner_grave(c,None);}}Ok(())}
 pub(crate) fn lc04_choose(&mut self,f:ResolutionFrame,mut p:Picks,seat:usize,a:&Action,ids:&[String])->RuleResult<()>{self.lc04_picks(&f,&p)?;let slot=p.chosen.len();if seat!=slot/4||ids.len()!=1||*a!=(Action{choice_id:a.choice_id.clone(),selected:Some(ids.to_vec()),..Action::new("choose")})||!self.lc04_options(slot,&p.chosen).iter().any(|o|o.id==ids[0]){return Err("卡德兰须由当前玩家选择实际合格对象".into())}p.chosen.push(Some(ids[0].clone()));self.lc04_offer(f,p)}
 pub(crate) fn validate_lc04_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();let mut check=|f:&ResolutionFrame|->RuleResult<()>{self.lc04_frame(f)?;if owned(f)&&!seen.insert(f.frame_id.clone()){return Err("卡德兰同帧重复续体".into())}Ok(())};for i in &self.stack{if let Some(f)=&i.frame{check(f)?;if owned(f)&&(i.card.is_some()||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.is_some()||f.cursor!=0){return Err("卡德兰响应外壳损坏".into())}}}for e in &self.effects{match e{Effect::Frame{frame}=>check(frame)?,Effect::DeathCaller{caller}=>check(&caller.frame)?,Effect::Declare{declaration:d}if related(&d.ability)=>{validate_ability(&d.source.card.definition,&d.ability)?;self.lc04_source(d.actor,&d.source)?;},_=>()}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Frame{frame:f,choice}=>{check(f)?;if owned(f)||matches!(choice,FrameChoice::LC04(_)){if !owned(f){return Err("卡德兰选择缺原帧".into())}let(opts,kind,title,seat)=match choice{FrameChoice::LC04(v)=>{self.lc04_picks(f,v)?;let slot=v.chosen.len();if slot>=self.players.len()*4{return Err("卡德兰完成批次不能仍待选".into())}(self.lc04_options(slot,&v.chosen),"lc04-sacrifice",Self::lc04_title(slot),slot/4)},FrameChoice::Discard{seat,redraw:false}if f.cursor>0&&f.cursor<f.steps.len()&&f.steps[f.cursor-1].context==*seat=>{(self.players[*seat].hand.iter().map(|c|self.option(c,*seat,None,None)).collect(),"discard","弃 1 张手牌".into(),*seat)},_=>return Err("卡德兰待选阶段或类型错误".into())};if opts.is_empty()||p.seat!=seat||p.choice.player_id!=player_id(seat)||p.choice.kind!=kind||p.choice.title!=title||p.choice.min!=Some(1)||p.choice.max!=Some(1)||p.choice.amount.is_some()||p.choice.allow_decline!=Some(false)||!p.choice.preview_cards.is_empty()||!same(&p.choice.options,&opts){return Err("卡德兰待选选项、玩家或数量损坏".into())}}},ChoiceResolution::Declare{declaration:d,..}if related(&d.ability)=>return Err("卡德兰强制触发不可改为可选".into()),_=>()}}Ok(())}
}
